'use strict';
// Reuse established copper components; retain server-side product/role/state checks.
const CoRefinement={
 t:(cn,en)=>CobaltUI.t(cn,en),
 metric(label,value,href='/inventory'){return '<a class="v34-kpi" href="'+esc(href)+'"><span>'+esc(label)+'</span><strong>'+esc(value??'—')+'</strong><span class="v34-card-arrow" aria-hidden="true">↗</span></a>';},
 normalize(){const root=document.querySelector('#page-content .co-page');if(!root||ProductContext.isCopper())return;root.classList.add('ux7-page');const production=/生产批次|production batch/i;
 for(const heading of [...root.querySelectorAll('h2,h3')])if(production.test(heading.textContent)){const next=heading.nextElementSibling;if(next?.classList.contains('business-table'))next.remove();heading.remove();}
 for(const label of [...root.querySelectorAll('label')])if(production.test(label.textContent))label.remove();
 for(const table of root.querySelectorAll('table')){const indices=[...table.querySelectorAll('thead tr:first-child th')].map((h,i)=>production.test(h.textContent)?i:-1).filter(i=>i>=0).reverse();for(const i of indices)for(const row of table.rows)row.cells[i]?.remove();}
 for(const p of [...root.querySelectorAll('p')])if(production.test(p.textContent))p.remove();for(const span of root.querySelectorAll('.co-work-table-guide span'))if(production.test(span.textContent))span.textContent=this.t('表格可左右滚动；袋号只读。','Scroll horizontally; bag numbers are read-only.');for(const dt of [...root.querySelectorAll('dt')])if(production.test(dt.textContent)){dt.nextElementSibling?.remove();dt.remove();}
 for(const grid of root.querySelectorAll('.co-stock-metrics,.co-work-metrics,.co-report-metrics,.shipping-kpis')){grid.classList.remove('co-stock-metrics','co-work-metrics','co-report-metrics','shipping-kpis');grid.classList.add('v34-kpi-grid');for(const card of grid.children){card.classList.remove('metric-card');card.classList.add('v34-kpi');const text=[...card.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE&&n.textContent.trim());if(text.length){const span=document.createElement('span');span.textContent=text.map(n=>n.textContent).join(' ');card.prepend(span);text.forEach(n=>n.remove());}}}
 for(const p of root.querySelectorAll('p')){if(/客户联系资料为两产品通用主数据|Customer contacts are shared master data/.test(p.textContent))p.textContent=this.t('氢氧化钴客户档案与阴极铜独立维护，修改不会同步到另一产品；合同仅引用钴客户档案。','Cobalt customer profiles are maintained independently from copper. Changes do not update the other product; cobalt contracts reference this directory only.');if(/Dispatch → Arrival → Waiting for a Future Loading Plan|派车 → 到场登记 → 等待后续装车计划/.test(p.textContent))p.textContent=this.t('派车 → 到场登记 → 创建装车计划 → 整批匹配生成装车单。','Dispatch → Arrival → Loading Plan → Whole-batch Match and Loading Order.');}
 for(const summary of root.querySelectorAll('summary'))if(/新增或编辑通用客户|Create or Edit Shared Customer/.test(summary.textContent))summary.textContent=this.t('新增或编辑钴客户','Create or Edit Cobalt Customer');if(location.pathname==='/customers'&&!new URLSearchParams(location.search).has('editor'))$('business-title').textContent=this.t('客户管理','Customer Management');for(const label of root.querySelectorAll('.v34-kpi > span:first-child')){const text=label.textContent.replace(/\s*kg\s*(\(MT\))/gi,' $1');if(text!==label.textContent)label.textContent=text;}if(location.pathname.startsWith('/receipts')){document.getElementById('business-title').textContent=this.t(root.querySelector('.co469-page')?'氢氧化钴入库与备货':location.pathname.endsWith('/work')?'氢氧化钴备货作业':location.pathname.endsWith('/new')?'新建氢氧化钴入库备货单':'氢氧化钴入库管理',root.querySelector('.co469-page')?'Cobalt Receipt and Preparation':location.pathname.endsWith('/work')?'Cobalt Preparation Work':location.pathname.endsWith('/new')?'Create Cobalt Receipt Preparation':'Cobalt Receipt Management');for(const a of root.querySelectorAll('a[href]')){const h=a.getAttribute('href');if(h==='/preparation')a.setAttribute('href','/receipts');else if(/^\/preparation\/[0-9a-f-]{36}(?:\?|$)/.test(h))a.setAttribute('href',h.replace('/preparation/','/receipts/'));}}
 },
 async create(saved){const opts=await API.request('/cobalt/options'),t=this.t,project=saved?.project_id||opts.projects[0]?.id;CobaltUI.page(t('新建氢氧化钴备货单','Create Cobalt Preparation'),'<form id="co-create" class="user-form"><div class="co-batch-identity"><label>'+t('备货批次号','Preparation Batch No.')+'<input id="co-preparation-number" readonly aria-readonly="true" value="RMM-CO-'+BusinessTime.today().slice(0,4)+'-XXX"><small>'+t('保存后自动生成','Assigned Automatically on Save')+'</small></label></div><div class="form-grid"><label>'+t('项目','Project')+'<select name="project_id" required>'+opts.projects.map(p=>'<option value="'+p.id+'" '+(p.id===project?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><label>'+t('仓库','Warehouse')+'<select name="warehouse_id" required></select></label><label>'+t('计划货位','Planned Location')+'<select name="planned_location_id"></select><small>'+t('实际货位在备货作业中确认。','Confirm actual placement during preparation.')+'</small></label><label>'+t('总袋数','Total Bags')+'<input type="number" name="total_bags" min="1" max="10000" step="1" required value="'+esc(saved?.total_bags||'')+'"></label></div><p class="co-note">'+t('每单生成一个备货批次。袋号由服务端按卢本巴希业务日期连续分配；保存后不可重复使用。','One order creates one preparation batch. The server allocates unique sequential bags using the Lubumbashi business date.')+'</p><p id="co-totals" class="co-note" aria-live="polite"></p><p>'+t('每袋初始预计毛重650kg、包装3kg、净重647kg；正式入库后在备货作业中确认实际重量、铅封和取样。','Initial expected weight: gross 650 kg, packaging 3 kg, net 647 kg. After formal receipt, confirm actual weights, seals and sampling in preparation work.')+'</p><p id="co-error" class="error" role="alert"></p><button id="co-save" class="button primary" type="submit">'+t('保存并查看备货单','Save and View Preparation')+'</button></form>');const form=$('co-create'),locations=()=>{const select=form.elements.planned_location_id,value=select.value||saved?.planned_location_id,rows=opts.locations.filter(l=>l.project_id===form.elements.project_id.value&&l.warehouse_id===form.elements.warehouse_id.value);select.innerHTML='<option value="">'+t(rows.length?'请选择货位':'暂无可选货位',rows.length?'Select Location':'No Available Locations')+'</option>'+rows.map(l=>'<option value="'+l.id+'" '+(l.id===value?'selected':'')+'>'+esc(l.code+' · '+(I18n.language==='en'?l.zone_name_en:l.zone_name))+'</option>').join('');},warehouse=()=>{form.elements.warehouse_id.innerHTML=opts.warehouses.filter(w=>w.project_id===form.elements.project_id.value).map(w=>'<option value="'+w.id+'" '+(w.id===saved?.warehouse_id?'selected':'')+'>'+esc(w.name)+'</option>').join('');locations();},total=()=>{const n=Number(form.elements.total_bags.value||0);$('co-totals').textContent=t('预计毛重：','Expected Gross: ')+(n*650).toLocaleString()+' kg · '+t('预计净重：','Expected Net: ')+(n*647).toLocaleString()+' kg';};warehouse();total();form.elements.project_id.onchange=warehouse;form.elements.warehouse_id.onchange=locations;form.elements.total_bags.oninput=total;form.onsubmit=async e=>{e.preventDefault();const body=CoRefinement.formValue();e.submitter.disabled=true;try{const r=await API.request('/cobalt/preparations',{method:'POST',body});ProductContext.dirty=false;await Router.go((location.pathname.startsWith('/receipts')?'/receipts/':'/preparation/')+r.id);}catch(err){$('co-error').textContent=err.message==='CO_STOCK_LOCATION_UNAVAILABLE'?t('货位已被占用或停用，请刷新后重新选择。','The location is occupied or inactive. Refresh and choose another.'):CobaltUI.error(err);e.submitter.disabled=false;}};ProductContext.dirty=false;},
 formValue(){const f=$('co-create');return {project_id:f.elements.project_id.value,warehouse_id:f.elements.warehouse_id.value,planned_location_id:f.elements.planned_location_id?.value||null,total_bags:Number(f.elements.total_bags.value)};},
 async receipts(){const t=this.t,q=new URLSearchParams(location.search),status=q.get('status')||'',page=Number(q.get('page')||1),d=await API.request('/cobalt/preparations?'+new URLSearchParams({status,page})),s=d.summary||{};CobaltUI.page(t('氢氧化钴入库管理','Cobalt Receipt Management'),'<div class="business-toolbar">'+(CobaltUI.can('co:create')?'<a id="co-receipt-new" class="button primary" href="/receipts/new">'+t('新建入库备货单','Create Receipt Preparation')+'</a>':'')+'<a class="button secondary" href="/preparation">'+t('备货管理','Preparation Management')+'</a></div><div class="ux7-workflow">'+t('物流建单并提交 → 现场主管审核 → 生产管理部审核 → 正式入库（备货作业中）','Create and submit → Site supervisor review → Production approval → Formal receipt (Preparing)')+'</div><div class="v34-kpi-grid">'+[['待提交','Draft',s.draft||0,'DRAFT'],['待现场主管审核','Awaiting Site Review',s.site_pending||0,'SITE_PENDING'],['待生产管理部审核','Awaiting Production Review',s.production_pending||0,'PRODUCTION_PENDING'],['已正式入库','Formally Received',s.received||0,'RECEIVED']].map(([cn,en,n,state])=>this.metric(t(cn,en),n,'/receipts?status='+state)).join('')+'</div><form id="co-receipt-filter" class="filters"><label>'+t('入库状态','Receipt Status')+'<select name="status"><option value="">'+t('全部','All')+'</option>'+Object.keys(CobaltUI.states).map(state=>'<option value="'+state+'" '+(state===status?'selected':'')+'>'+CobaltUI.status(state)+'</option>').join('')+'</select></label><button class="button secondary">'+t('查询','Search')+'</button></form><p class="co-note">'+t('生产管理部审批通过时一次性生成全部袋级实物库存；审批前不计入正式库存。','Production approval creates the complete bag-level physical inventory atomically. Pending approval is not formal stock.')+'</p>'+CobaltSalesUI.table([['入库备货单','Receipt Preparation'],['备货批次','Preparation Batch'],['业务日期','Business Date'],['袋数','Bags'],['状态','Status'],['操作','Actions']],d.items.map(p=>'<tr><td><a href="/receipts/'+p.id+'">'+esc(p.document_no)+'</a></td><td>'+esc(p.preparation_batch_no)+'</td><td>'+esc(p.business_date)+'</td><td>'+p.bag_count+'</td><td>'+CobaltUI.status(p.status)+'</td><td><a class="button secondary" href="/receipts/'+p.id+'">'+t('查看 / 审核','View / Review')+'</a></td></tr>'),'co-receipt-table')+CobaltStockUI.pager(page,d.total,50));$('co-receipt-filter').onsubmit=e=>{e.preventDefault();Router.go('/receipts?'+new URLSearchParams(new FormData(e.target)));};if($('co-stock-prev'))$('co-stock-prev').onclick=()=>Router.go('/receipts?'+new URLSearchParams({status,page:page-1}));if($('co-stock-next'))$('co-stock-next').onclick=()=>Router.go('/receipts?'+new URLSearchParams({status,page:page+1}));ProductContext.dirty=false;},
 async loading(){await CobaltLoadingUI.list();if($('co-loading-filter'))$('co-loading-filter').onsubmit=e=>{e.preventDefault();Router.go('/export-shipments?'+new URLSearchParams(new FormData(e.target)));};const title=$('business-title');title.textContent=this.t('氢氧化钴装车计划管理','Cobalt Loading Plan Management');const root=document.querySelector('.co-loading-page')||document.querySelector('.co-page');if(root&&!$('co-create-loading-order'))root.insertAdjacentHTML('afterbegin','<div class="business-toolbar">'+(CobaltUI.can('loading-plan:write')?'<a id="co-create-loading-order" class="button primary" href="/loading-plans/new?create_order=1">'+this.t('创建装车单','Create Loading Order')+'</a>':'')+'<a class="button secondary" href="/loading-plans">'+this.t('车辆到场登记','Vehicle Arrivals')+'</a><a class="button secondary" href="/loading-plans/query">'+this.t('装车计划查询','Loading Plans')+'</a></div><p class="co-note">'+this.t('选择销售计划、已到场车辆和已完成备货批次，保存计划后确认整批匹配，系统生成唯一装车单并锁定全部袋子。','Select a sales plan, arrived vehicle and completed preparation. Save the plan, then confirm the whole-batch match to create one loading order and reserve every bag.')+'</p>');}
};
const coOriginalPage=CobaltUI.page.bind(CobaltUI);CobaltUI.page=(title,html)=>{coOriginalPage(title,html);CoRefinement.normalize();};
CobaltUI.create=s=>CoRefinement.create(s);CobaltUI.formValue=()=>CoRefinement.formValue();
const coOriginalRoute=CobaltUI.route.bind(CobaltUI);CobaltUI.route=async p=>{const q=new URLSearchParams(location.search);if(q.has('production_batch')){q.delete('production_batch');history.replaceState({},'',location.pathname+(q.size?'?'+q:''));}if(p==='/receipts')return CoRefinement.receipts();if(p==='/receipts/new')return CoRefinement.create();if(/^\/receipts\/[0-9a-f-]{36}$/.test(p))return CobaltUI.detail(p.split('/')[2]);if(p==='/export-shipments')return CoRefinement.loading();await coOriginalRoute(p);CoRefinement.normalize();};
const coOriginalPageMatch=ProductContext.cobaltPage.bind(ProductContext);ProductContext.cobaltPage=p=>!ProductContext.isCopper()&&(/^\/receipts(?:\/(?:new|[0-9a-f-]{36}))?$/.test(p)||p==='/export-shipments')||coOriginalPageMatch(p);
const coOriginalPermission=Router.permission.bind(Router);Router.permission=p=>!ProductContext.isCopper()&&p==='/export-shipments'?'loading-plan:read':!ProductContext.isCopper()&&/^\/receipts(?:\/|$)/.test(p)?p.endsWith('/new')?'co:create':'co:read':coOriginalPermission(p);
const coOriginalForm=CobaltLoadingUI.form.bind(CobaltLoadingUI);CobaltLoadingUI.form=async function(id,saved){await coOriginalForm(id,saved);if(new URLSearchParams(location.search).get('create_order')==='1'){$('business-title').textContent=CoRefinement.t('创建氢氧化钴装车单','Create Cobalt Loading Order');if($('co-loading-save'))$('co-loading-save').textContent=CoRefinement.t('保存计划并继续整批匹配','Save Plan and Continue to Whole-batch Match');const tab=document.querySelector('.co-page a[href="/loading-plans/new"]');if(tab){tab.textContent=CoRefinement.t('创建装车单','Create Loading Order');tab.href='/loading-plans/new?create_order=1';}}};
const coOriginalLanguage=CobaltUI.languageChanged.bind(CobaltUI);CobaltUI.languageChanged=async()=>{if(location.pathname.startsWith('/receipts')&&!$('co-create'))return CobaltUI.route(location.pathname);return coOriginalLanguage();};
// Read-only presentation metadata is retired; server historical identities remain available for audit.
const coOriginalRequest=API.request.bind(API);API.request=async function(url,options){const r=await coOriginalRequest(url,options);if(typeof url==='string'&&url.startsWith('/cobalt/')&&!options?.binary){const strip=v=>{if(!v||typeof v!=='object')return;for(const k of Object.keys(v)){if(k==='production_batches')v[k]=[];else if(k==='production_batch_code')v[k]='';else strip(v[k]);}};strip(r);}return r;};
const coOriginalInit=Router.init.bind(Router);Router.init=async function(...args){const r=await coOriginalInit(...args),page=$('page-content');let pending=false;if(page)new MutationObserver(()=>{if(pending||ProductContext.isCopper())return;pending=true;requestAnimationFrame(()=>{pending=false;CoRefinement.normalize();});}).observe(page,{childList:true,subtree:true});return r;};

const coOriginalError=CobaltUI.error.bind(CobaltUI);CobaltUI.error=e=>e.message==='CO_INVALID_COUNTS'?CoRefinement.t('袋数须为1至10000的整数','Bag count must be a whole number from 1 to 10,000'):e.message==='CO_TOTAL_MISMATCH'?CoRefinement.t('袋数与备货单总数不一致','Bag count does not match the preparation total'):coOriginalError(e);

// Draft detail exposes the existing read-only match preview without another discovery click.
const coOriginalLoadingDetail=CobaltLoadingUI.detail.bind(CobaltLoadingUI);CobaltLoadingUI.detail=async function(id){await coOriginalLoadingDetail(id);if(this.detailData?.plan?.status==='DRAFT'&&CobaltUI.can('loading-plan:match'))$('co-loading-check')?.click();};
